using System.Security.Claims;using EverestRemit.Api.DTOs;using EverestRemit.Api.Interfaces;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace EverestRemit.Api.Controllers;
[ApiController,Route("api/transfers"),Authorize]public sealed class TransfersController(ITransferService s):ControllerBase{string U=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
[HttpGet("me"),Authorize(Roles="User")]public async Task<IActionResult> Mine(CancellationToken ct)=>Ok(await s.GetMineAsync(U,ct));[HttpPost,Authorize(Roles="User")]public async Task<IActionResult> Create(CreateTransferRequest r,CancellationToken ct){try{return Ok(await s.CreateAsync(U,r,ct));}catch(InvalidOperationException e){return BadRequest(new{message=e.Message});}}
[HttpGet,Authorize(Roles="Admin")]public async Task<IActionResult> All(CancellationToken ct)=>Ok(await s.GetAllAsync(ct));[HttpPatch("{id:int}/status"),Authorize(Roles="Admin")]public async Task<IActionResult> Status(int id,UpdateTransferStatusRequest r,CancellationToken ct){try{var x=await s.UpdateStatusAsync(id,r,ct);return x==null?NotFound():Ok(x);}catch(InvalidOperationException e){return BadRequest(new{message=e.Message});}}}
